public sealed record InboundToken(
    string Scheme,
    string? Version,
    string? Issuer,
    DateTimeOffset? ExpiresAt,
    string? ApiKeyPrefix);

public static AuthDecision Decide(InboundToken token, DateTimeOffset utc) => token switch
{
    { Scheme: "LTI", Version: "1.3", Issuer: { Length: > 0 } issuer }
        => new AuthDecision("lti13", issuer, Roles: ["learner"]),
    { Scheme: "Bearer", ExpiresAt: DateTimeOffset exp } when exp > utc
        => new AuthDecision("oidc", token.Issuer ?? "unknown", Roles: ["user"]),
    { Scheme: "ApiKey", ApiKeyPrefix: "sk_live" }
        => new AuthDecision("api-key", "legacy", Roles: ["service"]),
    { Scheme: "Bearer" }
        => throw new InvalidOperationException("Bearer token expired or missing exp."),
    _ => throw new InvalidOperationException($"Unsupported token {token.Scheme}.")
};

public sealed record AuthDecision(string Provider, string Subject, string[] Roles);

public static bool IsLti13(InboundToken token) => token is
{
    Scheme: "LTI",
    Version: { } version,
    Issuer: { Length: > 0 }
} && version.StartsWith("1.3", StringComparison.Ordinal);

public static string RequireContextId(string[] customClaims) => customClaims switch
{
    [var contextId, ..] when !string.IsNullOrWhiteSpace(contextId) => contextId,
    [] => throw new InvalidOperationException("LTI launch missing custom claims."),
    _ => throw new InvalidOperationException("First custom claim must be the context id.")
};

public abstract record AuthToken;
public sealed record LtiToken(string Issuer, string Version) : AuthToken;
public sealed record OidcBearer(DateTimeOffset Expires) : AuthToken;
public sealed record ApiKeyToken(string KeyId) : AuthToken;

AuthDecision Decide(AuthToken token) => token switch
{
    LtiToken { Version: var v } when v.StartsWith("1.3") => AllowLti(v),
    OidcBearer { Expires: var exp } when exp > DateTimeOffset.UtcNow => AllowOidc(),
    ApiKeyToken { KeyId: var id } => AllowApiKey(id),
    _ => throw new UnauthorizedAccessException($"unknown token shape: {token.GetType().Name}")
};
